def validate_gate_dependencies(project: Path, state: dict, gate: dict) -> None:
    lowered = str(gate.get("label", "")).lower()
    backend_check = any(token in lowered for token in (
        "backend formatting", "backend lint", "backend vet",
        "module-focused compile", "cross-module tests", "backend focused tests", "backend full tests",
    ))
    if not backend_check:
        return
    current = dict(identities(project), project=project)
    finalization = next((
        value for value in state["gates"].values()
        if value.get("active", True) and "local composition finalized" in str(value.get("label", "")).lower()
    ), None)
    if finalization is None or effective_status(finalization, current) != "passed":
        raise GateError("backend compile/test Gate requires a current local-composition finalization Gate")


def mandatory_gate(label: str) -> bool:
    lowered = label.lower()
    return bool(
        required_evidence_type(label)
        or REQUIREMENT_COVERAGE_MARKER in lowered
        or "all preceding stages complete" in lowered
        or "no open" in lowered
        or "no blocked finding" in lowered
        or "no requirement remains" in lowered
    )


COMMAND_CATEGORIES = (
    ("dependency installation", ("npm ci", "npm install", "pnpm install", "yarn install")),
    ("typecheck", ("tsc ", "npm run typecheck", "pnpm typecheck", "yarn typecheck")),
    ("lint", ("npm run lint", "pnpm lint", "yarn lint", "eslint ", "golangci-lint")),
    ("test", ("npm test", "npm run test", "pnpm test", "yarn test", "vitest", "jest", "go test")),
    ("production build", ("npm run build", "pnpm build", "yarn build", "vite build")),
    ("formatting", ("gofmt", "go fmt")),
    (" vet", ("go vet",)),
)


def validate_command_for_gate(label: str, command: list[str]) -> None:
    lowered = " ".join(command).lower()
    label_value = f" {label.lower()} "
    allowed: list[str] = []
    for category_token, category_commands in COMMAND_CATEGORIES:
        if category_token in label_value:
            allowed.extend(category_commands)
    if allowed and not any(token in lowered for token in allowed):
        raise GateError(f"command does not prove Gate '{label}'")


def require_gate(state: dict, gate_id: str) -> dict:
    gate = state["gates"].get(gate_id)
    if not gate or not gate.get("active", True):
        raise GateError(f"unknown active gate ID: {gate_id}")
    return gate


def bind_gate(gate: dict, status: str, evidence_type: str, evidence: list[dict],
              bindings: list[str], identity: dict, note: str) -> None:
    if status not in STATUSES:
        raise GateError("unsupported gate status")
    if status in {"passed", "failed", "accepted_limitation"} and not evidence:
        raise GateError(f"{status} requires evidence")
    if status in {"not_applicable", "accepted_limitation"} and not note.strip():
        raise GateError(f"{status} requires an explicit note")
    gate.update({
        "status": status,
        "evidence_type": evidence_type,
        "evidence": evidence,
        "bindings": bindings,
        "source_sha": identity["source_sha"],
        "blueprint_sha": identity["blueprint_sha"],
        "runtime_manifest_sha": identity["runtime_manifest_sha"],
        "verified_at": now(),
        "note": note.strip(),
    })


def save(project: Path, session: str, state: dict) -> None:
    state["current_identity"] = identities(project)
    state["updated_at"] = now()
    atomic_json(state_path(project, session), state)
    render_todo(project, session, state)


def command_sync(args, project: Path, session: str) -> int:
    state = sync_gates(project, session, load_state(project, session))
    save(project, session, state)
    print(json.dumps(status_document(project, state), ensure_ascii=False, separators=(",", ":")))
    return 0


def command_list(args, project: Path, session: str) -> int:
    state = sync_gates(project, session, load_state(project, session))
    save(project, session, state)
    rows = [{key: gate[key] for key in ("gate_id", "stage", "label", "status")} for gate in state["gates"].values() if gate.get("active", True)]
    print(json.dumps({"contract_version": CONTRACT_VERSION, "gates": rows}, ensure_ascii=False, separators=(",", ":")))
    return 0


def command_attach(args, project: Path, session: str) -> int:
    state = sync_gates(project, session, load_state(project, session))
    gate = require_gate(state, args.gate_id)
    if args.evidence_type not in EVIDENCE_TYPES:
        raise GateError("unsupported evidence type")
    required_type = required_evidence_type(gate["label"])
    if args.status == "passed" and required_type and args.evidence_type != required_type:
        raise GateError(f"Gate requires evidence type {required_type}")
    evidence = [evidence_item(project, value) for value in args.evidence_path]
    for item in evidence:
        validate_receipt(project, item, args.evidence_type)
    bindings = sorted(set(args.bind))
    if any(value not in BINDINGS for value in bindings):
        raise GateError("unsupported identity binding")
    if args.status == "passed":
        validate_requirement_coverage(project, gate, evidence)
        validate_source_finalization(project, gate, evidence, bindings)
        validate_gate_dependencies(project, state, gate)
        if REQUIREMENT_COVERAGE_MARKER in gate["label"].lower() and "source" not in bindings:
            raise GateError("all requirements implemented must bind the current source identity")
    machine_note = validate_frontend_not_present(project, gate, args.status)
    note = f"{args.note} {machine_note}".strip() if machine_note else args.note
    bind_gate(gate, args.status, args.evidence_type, evidence, bindings, identities(project), note)
    save(project, session, state)
    print(json.dumps(gate, ensure_ascii=False, separators=(",", ":")))
    return 0


def command_mark(args, project: Path, session: str) -> int:
    if args.status not in {"pending", "not_applicable"}:
        raise GateError("mark supports only pending or not_applicable; use run/attach for evidenced states")
    state = sync_gates(project, session, load_state(project, session))
    gate = require_gate(state, args.gate_id)
    if args.status == "not_applicable" and mandatory_gate(gate["label"]):
        raise GateError("mandatory Gate cannot be marked not_applicable")
    machine_note = validate_frontend_not_present(project, gate, args.status)
    note = f"{args.note} {machine_note}".strip() if machine_note else args.note
    bind_gate(gate, args.status, "", [], [], identities(project), note)
    save(project, session, state)
    print(json.dumps(gate, ensure_ascii=False, separators=(",", ":")))
    return 0


def command_run(args, project: Path, session: str) -> int:
    if not args.command:
        raise GateError("run requires a command after --")
    bindings = sorted(set(args.bind))
    if not bindings or any(value not in BINDINGS for value in bindings):
        raise GateError("run requires valid identity bindings")
    state = sync_gates(project, session, load_state(project, session))
    gate = require_gate(state, args.gate_id)
    validate_gate_dependencies(project, state, gate)
    validate_command_for_gate(gate["label"], args.command)
    started_at = now()
    completed = subprocess.run(args.command, cwd=project, capture_output=True, text=False, check=False)
    root = evidence_root(project, session)
    root.mkdir(parents=True, exist_ok=True)
    receipt_path = root / f"{slug(args.gate_id)}-{datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')}.json"
    receipt = {
        "contract_version": "domainry-development-gate-command-v1",
        "gate_id": args.gate_id,
        "command": args.command,
        "cwd": ".",
        "started_at": started_at,
        "verified_at": now(),
        "exit_code": completed.returncode,
        "stdout_sha256": sha256_bytes(completed.stdout),
        "stderr_sha256": sha256_bytes(completed.stderr),
        "stdout_bytes": len(completed.stdout),
        "stderr_bytes": len(completed.stderr),
    }
    atomic_json(receipt_path, receipt)
    evidence = [evidence_item(project, str(receipt_path))]
    status = "passed" if completed.returncode == 0 else "failed"
    bind_gate(gate, status, "command_receipt", evidence, bindings, identities(project), args.note)
    save(project, session, state)
    output = dict(gate, command_exit_code=completed.returncode)
    print(json.dumps(output, ensure_ascii=False, separators=(",", ":")))
    return 0 if completed.returncode == 0 else 1


def command_finding(args, project: Path, session: str) -> int:
    if args.status not in {"open", "resolved", "accepted_limitation"}:
        raise GateError("unsupported finding status")
    if args.status != "resolved" and not args.note.strip():
        raise GateError("open and accepted limitation findings require a note")
    state = sync_gates(project, session, load_state(project, session))
    evidence = [evidence_item(project, value) for value in args.evidence_path]
