def evidence_item(project: Path, raw_path: str) -> dict:
    candidate = Path(raw_path).expanduser()
    path = (candidate if candidate.is_absolute() else project / candidate).resolve(strict=True)
    if project != path and project not in path.parents:
        raise GateError("evidence path must remain inside the project")
    if path.is_symlink() or not path.is_file() or path.stat().st_size <= 0:
        raise GateError("evidence must be a non-empty regular file")
    return {
        "path": path.relative_to(project).as_posix(),
        "sha256": sha256_file(path),
        "bytes": path.stat().st_size,
    }


