    if evidence_type not in {"cli_receipt", "command_receipt"}:
        return
    path = project / item["path"]
    try:
        document = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as error:
        raise GateError("receipt evidence must be valid JSON") from error
    if evidence_type == "command_receipt":
        if document.get("contract_version") != "domainry-development-gate-command-v1" or document.get("exit_code") != 0:
            raise GateError("command receipt is not successful")
        return
    states = []
    if isinstance(document, dict):
        for key in ("state", "status", "result"):
            if isinstance(document.get(key), str):
                states.append(document[key].lower())
    if any(value in {"failed", "error", "invalid", "blocked"} for value in states):
        raise GateError("CLI receipt reports failure")


