func SendOverdueReminder(ctx context.Context, caps capabilities.SendOverdueReminderCapabilities, input capabilities.SendOverdueReminderInput) (capabilities.SendOverdueReminderOutput, error) {
	location, err := time.LoadLocation("Asia/Shanghai")
	if err != nil {
		return capabilities.SendOverdueReminderOutput{}, err
	}
	scheduledAt := input.ScheduledAt.In(location)
	if scheduledAt.Weekday() == time.Saturday || scheduledAt.Weekday() == time.Sunday {
		return capabilities.SendOverdueReminderOutput{Created: false}, nil
	}

	targetID := caps.Execution.TargetID()
	request, err := caps.ServiceRequest.Get(ctx, targetID)
	if err != nil {
		return capabilities.SendOverdueReminderOutput{}, err
	}
	if request.Status != schema.ServiceRequestStatus("dispatched") || request.DispatchedAt == nil || request.AssignedUserID == nil {
		return capabilities.SendOverdueReminderOutput{Created: false}, nil
	}
	if !request.DispatchedAt.Before(input.ScheduledAt.Add(-48 * time.Hour)) {
		return capabilities.SendOverdueReminderOutput{Created: false}, nil
	}

	businessDate := time.Date(scheduledAt.Year(), scheduledAt.Month(), scheduledAt.Day(), 0, 0, 0, 0, location)
	dedupeKey := string(targetID) + ":" + businessDate.Format("2006-01-02")
	exists, err := caps.OverdueReminder.Exists(ctx, data.NewOverdueReminderQuery().WhereDedupeKeyEqual(dedupeKey))
	if err != nil {
		return capabilities.SendOverdueReminderOutput{}, err
	}
	if exists {
		return capabilities.SendOverdueReminderOutput{Created: false}, nil
	}

	recipient := schema.NewOverdueReminderRecipientUserIDReference(request.AssignedUserID.ID())
	reminder, err := caps.OverdueReminder.Create(ctx, schema.CreateOverdueReminder{
		BusinessDate:       businessDate,
		DedupeKey:          dedupeKey,
		OwnerDepartmentID:  request.OwnerDepartmentID,
		OwnerDepartmentPath: request.OwnerDepartmentPath,
		RecipientUserID:    &recipient,
		SentAt:             input.ScheduledAt,
		ServiceRequestID:   schema.NewOverdueReminderServiceRequestIDReference(targetID),
	})
	if err != nil {
		return capabilities.SendOverdueReminderOutput{}, err
	}

	if _, err = caps.Notifications.Dispatch(ctx, capabilities.SendOverdueReminderNotificationIntent{
		EventType:        "service_request.overdue",
		SourceEventID:    dedupeKey,
		RecipientUserIDs: []string{string(request.AssignedUserID.ID())},
		Surface:          "business_workspace",
		SubjectObjectKey: "service_request",
		SubjectRecordID:  string(targetID),
		SubjectVersion:   request.UpdatedAt,
		DedupeKey:        "service_request.overdue:" + dedupeKey,
		GroupKey:         "service_request:" + string(targetID),
		Alert:            true,
		OccurredAt:       input.ScheduledAt,
	}); err != nil {
		return capabilities.SendOverdueReminderOutput{}, err
	}

	return capabilities.SendOverdueReminderOutput{
		Created:           true,
		OverdueReminderID: &reminder.ID,
	}, nil
}
