// SubmitServiceRequest implements the project-owned service_request.submit_service_request Handler.
func SubmitServiceRequest(ctx context.Context, caps capabilities.SubmitServiceRequestCapabilities, input capabilities.SubmitServiceRequestInput) (capabilities.SubmitServiceRequestOutput, error) {
	principal := caps.Execution.Principal()
	if !principal.Known || principal.UserID == "" || input.RequestID == "" || input.FaultDescription == "" {
		return capabilities.SubmitServiceRequestOutput{}, reject("validation.invalid_request")
	}

	profiles, err := caps.CustomerProfile.List(ctx, data.NewCustomerProfileQuery().
		WhereIdentityUserIDEqual(schema.NewCustomerProfileIdentityUserIDReference(schema.IdentityUserID(principal.UserID))).
		Page(1, 2))
	if err != nil {
		return capabilities.SubmitServiceRequestOutput{}, err
	}
	if len(profiles) != 1 {
		return capabilities.SubmitServiceRequestOutput{}, reject("authorization.forbidden")
	}

	device, err := caps.Device.Get(ctx, input.DeviceID)
	if err != nil {
		return capabilities.SubmitServiceRequestOutput{}, err
	}
	if device.CustomerProfileID.ID() != profiles[0].ID {
		return capabilities.SubmitServiceRequestOutput{}, reject("authorization.forbidden")
	}

	created, err := caps.ServiceRequest.Create(ctx, schema.CreateServiceRequest{
		CustomerProfileID: schema.NewServiceRequestCustomerProfileIDReference(profiles[0].ID),
		DeviceID:          schema.NewServiceRequestDeviceIDReference(device.ID),
		FaultDescription:  input.FaultDescription,
		PreferredVisitAt:  input.PreferredVisitAt,
		Status:            schema.ServiceRequestStatusSubmitted,
		SubmittedAt:       input.SubmittedAt,
	})
	if err != nil {
		return capabilities.SubmitServiceRequestOutput{}, err
	}

	return capabilities.SubmitServiceRequestOutput{
		ServiceRequestID: created.ID,
		Status:           schema.ServiceRequestSubmitServiceRequestStatusSubmitted,
	}, nil
}
