// DecideWarrantyWaiver implements the project-owned warranty_waiver.decide_warranty_waiver Handler.
func DecideWarrantyWaiver(ctx context.Context, caps capabilities.DecideWarrantyWaiverCapabilities, input capabilities.DecideWarrantyWaiverInput) (capabilities.DecideWarrantyWaiverOutput, error) {
	principal := caps.Execution.Principal()
	if !principal.Known || principal.UserID == "" {
		return capabilities.DecideWarrantyWaiverOutput{}, reject("authorization.forbidden")
	}

	decision := string(input.Decision)
	approved := decision == "approve" || decision == "approved"
	rejected := decision == "reject" || decision == "rejected"
	if !approved && !rejected {
		return capabilities.DecideWarrantyWaiverOutput{}, reject("validation.invalid_decision")
	}
	if rejected && (input.RejectionReason == nil || strings.TrimSpace(*input.RejectionReason) == "") {
		return capabilities.DecideWarrantyWaiverOutput{}, reject("validation.rejection_reason_required")
	}

	targetID := caps.Execution.TargetID()
	waiver, err := caps.WarrantyWaiver.GetForUpdate(ctx, targetID)
	if err != nil {
		return capabilities.DecideWarrantyWaiverOutput{}, err
	}
	if waiver.Status != schema.WarrantyWaiverStatus("pending") {
		return capabilities.DecideWarrantyWaiverOutput{}, reject("state.conflict")
	}

	mutation := data.NewWarrantyWaiverUpdate(targetID).
		WithExpectedUpdatedAt(waiver.UpdatedAt).
		RequireStatusEqual(schema.WarrantyWaiverStatus("pending"), "state.conflict").
		SetDecidedAt(input.DecidedAt).
		SetDecidedByUserID(principal.UserID)
	outputStatus := schema.WarrantyWaiverDecideWarrantyWaiverStatusRejected
	if approved {
		mutation = mutation.SetStatus(schema.WarrantyWaiverStatus("applied")).ClearRejectionReason()
		outputStatus = schema.WarrantyWaiverDecideWarrantyWaiverStatusApproved
	} else {
		mutation = mutation.SetStatus(schema.WarrantyWaiverStatus("rejected")).SetRejectionReason(*input.RejectionReason)
	}
	updated, err := caps.WarrantyWaiver.ConditionalUpdate(ctx, mutation)
	if err != nil {
		return capabilities.DecideWarrantyWaiverOutput{}, err
	}

	if approved {
		waiverReference := schema.NewFeeLedgerWarrantyWaiverIDReference(updated.ID)
		if _, err = caps.FeeLedger.Create(ctx, schema.CreateFeeLedger{
			Amount:             schema.FeeLedgerAmount(updated.RequestedAmount),
			CalculationTrace:   "applied_waiver=requested_amount",
			InputSnapshot:      `{"decision":"manager_approved"}`,
			Kind:               schema.FeeLedgerKind("waiver"),
			LineageKey:         "warranty_waiver:" + string(updated.ID),
			OccurredAt:         input.DecidedAt,
			PolicySnapshot:     updated.PolicySnapshot,
			ServiceRequestID:   schema.NewFeeLedgerServiceRequestIDReference(updated.ServiceRequestID.ID()),
			WarrantyWaiverID:   &waiverReference,
		}); err != nil {
			return capabilities.DecideWarrantyWaiverOutput{}, err
		}
	}

	if updated.RequesterUserID == nil || *updated.RequesterUserID == "" {
		return capabilities.DecideWarrantyWaiverOutput{}, reject("waiver.requester_missing")
	}
	if _, err = caps.Notifications.Dispatch(ctx, capabilities.DecideWarrantyWaiverNotificationIntent{
		EventType:        "warranty_waiver.resolved",
		SourceEventID:    "warranty_waiver.resolved:" + string(updated.ID),
		RecipientUserIDs: []string{*updated.RequesterUserID},
		Surface:          "business_workspace",
		SubjectObjectKey: "warranty_waiver",
		SubjectRecordID:  string(updated.ID),
		SubjectVersion:   updated.UpdatedAt,
		DedupeKey:        "warranty_waiver.resolved:" + string(updated.ID),
		GroupKey:         "service_request:" + string(updated.ServiceRequestID.ID()),
		Alert:            true,
		OccurredAt:       input.DecidedAt,
	}); err != nil {
		return capabilities.DecideWarrantyWaiverOutput{}, err
	}
