def validate_requirement_coverage(project: Path, gate: dict, evidence: list[dict]) -> None:
    label = str(gate.get("label", "")).lower()
    if REQUIREMENT_COVERAGE_MARKER not in label:
        return
    managed_evidence = (project / ".domainry" / "builder" / "evidence").resolve()
    for item in evidence:
        path = project / item["path"]
        if managed_evidence not in path.resolve().parents:
            continue
        try:
            document = json.loads(path.read_text(encoding="utf-8"))
        except json.JSONDecodeError:
            continue
        items = document.get("items")
        complete_items = (
            isinstance(items, list)
            and bool(items)
            and all(
                isinstance(value, dict)
                and value.get("state") == "implemented"
                and isinstance(value.get("evidence"), dict)
                and bool(value["evidence"])
                and isinstance(value.get("gaps"), list)
                and not value["gaps"]
                for value in items
            )
        )
        if (
            document.get("contract_version") == "domainry-builder-v6-requirement-coverage-v1"
            and document.get("state") == "passed"
            and document.get("completion_percent") == 100
            and document.get("total_count") == len(items or [])
            and document.get("implemented_count") == len(items or [])
            and document.get("partial_count") == 0
            and document.get("missing_count") == 0
            and complete_items
        ):
            return
    raise GateError("all requirements implemented requires a current 100% requirement coverage receipt")


def required_evidence_type(label: str) -> str:
    lowered = label.lower()
    if "local composition finalized" in lowered:
        return "cli_receipt"
    command_tokens = (
        "dependency installation", "typecheck", " lint ", "lint passes",
        " tests pass", "focused tests", "full tests", "production build",
        "backend formatting", "backend vet",
    )
    if any(token in f" {lowered} " for token in command_tokens):
        return "command_receipt"
    if REQUIREMENT_COVERAGE_MARKER in lowered:
        return "cli_receipt"
    return ""


def validate_source_finalization(project: Path, gate: dict, evidence: list[dict], bindings: list[str]) -> None:
    if "local composition finalized" not in str(gate.get("label", "")).lower():
        return
    if "source" not in bindings:
        raise GateError("local composition finalization must bind the current source identity")
    required = {
        "backend/generated/composition/action_registry.gen.go",
        "backend/generated/composition/connector_registry.gen.go",
        "backend/generated/composition/extensions.gen.go",
    }
    for item in evidence:
        path = project / item["path"]
        try:
            document = json.loads(path.read_text(encoding="utf-8"))
        except json.JSONDecodeError:
            continue
        files = document.get("files")
        owned = {
            value.get("path"): value.get("sha256")
            for value in files or []
            if isinstance(value, dict) and value.get("owner") == "local_composition"
        }
        if document.get("contract_version") == "domainry-source-finalization-receipt-v2" and required <= owned.keys():
            for relative in required:
                target = project / relative
                if target.is_symlink() or not target.is_file() or sha256_file(target) != owned[relative]:
                    break
            else:
                return
    raise GateError("local composition finalization requires the complete current finalization receipt")


